```yaml
name: Merge Queue Cleanup
on:
  schedule:
    - cron: '*/5 * * * *'
  workflow_dispatch: {}

jobs:
  cleanup-unmergeable-prs:
    runs-on: ubuntu-latest
    steps:
      - name: Get unmergeable PRs from merge queue
        id: get_unmergeable
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: queue } = await github.rest.pulls.list(
              {
                owner: context.repo.owner,
                repo: context.repo.repo,
                state: 'open',
                sort: 'updated',
                direction: 'desc'
              }
            );

            const unmergeablePRs = queue.filter(pr => 
              pr.mergeable_state === 'unmergeable' && 
              pr.head.ref.startsWith('merge-queue/')
            );

            core.setOutput('pr_numbers', JSON.stringify(unmergeablePRs.map(pr => pr.number)));
            core.setOutput('pr_count', unmergeablePRs.length.toString());

      - name: Remove unmergeable PRs from merge queue
        if: steps.get_unmergeable.outputs.pr_count != '0'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumbers = JSON.parse('${{ steps.get_unmergeable.outputs.pr_numbers }}');

            for (const prNumber of prNumbers) {
              try {
                // Remove from merge queue by disabling auto-merge
                await github.rest.pulls.update({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  pull_number: prNumber,
                  maintainer_can_modify: false,
                  title: '',
                  body: ''
                });

                // Post comment explaining removal
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: prNumber,
                  body: `This PR has been removed from the merge queue because it's marked as unmergeable. Please rebase your branch to resolve conflicts and then add this PR back to the merge queue.\n\ncc @${context.actor}`
                });

                console.log(`Removed PR #${prNumber} from merge queue`);
              } catch (error) {
                console.error(`Failed to process PR #${prNumber}:`, error);
              }
            }
